referenceSolutions.javascript:
function risingLabelsEvenKeyCensus(readings, k) {
  const a=readings; let out=[];
  const tails=[];for(const x of a){let l=0,r=tails.length;while(l<r){const m=(l+r)>>1;if(tails[m]<x)l=m+1;else r=m;}tails[l]=x;out.push(l+1);}
  return out.filter(x=>x%2===0).length;
}

